import React from 'react';
import './suggestion.scss';
import loading from './load.png';
var Rating = require('react-rating').default;
class Suggestion extends React.Component
{
    constructor(props)
    {
        super(props);
        
        this.state = {"link":null,"desc":null,"img_src":null,"loaded":false, "title":null, width: window.innerWidth, "rating":0, "date":null};
        this.loaddata(this.props.name);
    }
                
    changeRating( newRating ) {
        this.setState({
          rating: newRating
        });
    }
    async loaddata(name)
    {
        const base  = "https://kitsu.io/api/edge"
        const search = "/anime?filter[text]=" + name;
        const promise = await fetch(base+search);
        const result = await promise.json()
        const anime = result.data[0].attributes;
        var img_src;
        if (window.innerHeight/window.innerWidth < 1)
        {
            if (anime.coverImage == null)
            {
                img_src = anime.posterImage.original;
            }
            else
            {
                img_src  = anime.coverImage.original;
            }
         
        }
        else
        {
            img_src = anime.posterImage.small;
        }
        const link = "https://www.youtube.com/watch?v=" + anime.youtubeVideoId;
        const date = anime.endDate.slice(0, 4);
        const rating = anime.averageRating;
        console.log(rating);
        const desc = anime.synopsis;
        const title = anime.titles.en;
        const jp_title = anime.titles.ja_jp + '\t\t'
        this.setState({"link":link,"desc":desc,"img_src":img_src,"loaded":true,"title":title, "jp_title":jp_title, "rating":rating, "date":date});
        this.props.new_img(this.state.img_src);
        
    
    }

    render()
    {   
        if (this.state.loaded === true)
        {
        return (
        <div className='result-container'>
        <a style={{textDecoration:"none"}} href = {this.state.link}>
        <h1 id = "title">{this.state.title}</h1> <i class="hide fa-3x fab fa-youtube"></i>
        </a>
        <p id = "date">{this.state.date}</p>
        <hr />
        <h2  id="alttitle">{this.state.jp_title}</h2> 
        <div class = "star">
        <Rating  emptySymbol= {<i style={{color:"rgb(96, 96, 96)"}} class="far fa-star"></i>} 
        fullSymbol={<i style={{color:"rgb(96, 96, 96)"}} class="fas fa-star"></i>} 
        start={0} stop={100} step={20} fractions={10} initialRating={this.state.rating} />
        </div>
            <p className="desc-container">
                    {this.state.desc}
            </p>
        </div>
        
        );
        }
        else
        {
            return (<div> <img id="load" src={loading} /> </div>);
            
        }
    }
}

export default Suggestion;